"""The sudoers drop-in of the agent: generated by the helper, checked here.

The drop-in is the privilege boundary of the agent package. It is never written
by hand: ``spot-agent-priv --print-sudoers --user spot-agent`` renders it from
the same template table the helper enforces, and the package build installs that
output unchanged. This module runs the helper, and refuses any output that is
not exactly the narrow shape the helper is meant to produce: one exact command
per template, no wildcard, no ``ALL`` command, nothing for another user.

Standard library only.
"""

from __future__ import annotations

import re
import subprocess
from pathlib import Path

AGENT_USER = "spot-agent"
HELPER_PATH = "/usr/libexec/spot-agent/spot-agent-priv"
INSTALLED_PATH = "/etc/sudoers.d/spot-agent"
INSTALLED_MODE = 0o440

#: A template name such as ``service.restart``.
NAME = re.compile(r"[a-z]+\.[a-z]+")
#: One command of the alias: the helper, ``run``, one template name. Nothing else.
COMMAND = re.compile(re.escape(HELPER_PATH) + r" run (" + NAME.pattern + r")")
WILDCARD_CHARS = set("*?[]{}")


class SudoersError(Exception):
    """The drop-in is not the shape the helper is supposed to generate."""


def generate(helper: Path, user: str = AGENT_USER) -> str:
    """Run ``helper --print-sudoers --user USER`` and return its (checked) output."""
    if not helper.is_file():
        raise SudoersError(f"helper binary not found: {helper}")
    run = subprocess.run(
        [str(helper), "--print-sudoers", "--user", user],
        capture_output=True, text=True, check=False, timeout=30,
    )
    if run.returncode != 0:
        raise SudoersError(f"helper --print-sudoers exited {run.returncode}")
    check(run.stdout, user)
    return run.stdout


def parse_commands(text: str, user: str = AGENT_USER) -> list[str]:
    """Return the template names the drop-in allows, validating the whole file.

    The accepted grammar: comments, blank lines, one ``Defaults:USER`` line, one
    ``Cmnd_Alias SPOT_AGENT_PRIV = cmd, cmd, ...`` (backslash continuations) and one
    ``USER ALL=(root) NOPASSWD: SPOT_AGENT_PRIV`` line. Anything else is an error.
    """
    if "\r" in text or "\0" in text:
        raise SudoersError("carriage return or NUL in the drop-in")
    joined = text.replace("\\\n", " ")
    alias_names: list[str] | None = None
    user_line = False
    for raw in joined.split("\n"):
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        if line.startswith(f"Defaults:{user} "):
            options = [o.strip() for o in line.split(" ", 1)[1].split(",")]
            if any(o not in ("!requiretty", "!visiblepw") for o in options):
                raise SudoersError(f"unexpected Defaults option: {line!r}")
            continue
        if line.startswith("Cmnd_Alias SPOT_AGENT_PRIV ="):
            if alias_names is not None:
                raise SudoersError("Cmnd_Alias defined twice")
            body = line.split("=", 1)[1]
            alias_names = []
            for command in body.split(","):
                command = " ".join(command.split())
                match = COMMAND.fullmatch(command)
                if match is None:
                    raise SudoersError(f"command is not 'helper run NAME': {command!r}")
                if WILDCARD_CHARS & set(command):
                    raise SudoersError(f"wildcard in command: {command!r}")
                alias_names.append(match.group(1))
            continue
        if line == f"{user} ALL=(root) NOPASSWD: SPOT_AGENT_PRIV":
            if user_line:
                raise SudoersError("user rule given twice")
            user_line = True
            continue
        raise SudoersError(f"line outside the generated shape: {line!r}")
    if not alias_names:
        raise SudoersError("no Cmnd_Alias SPOT_AGENT_PRIV")
    if not user_line:
        raise SudoersError("no user rule")
    if len(set(alias_names)) != len(alias_names):
        raise SudoersError("a template is listed twice")
    return alias_names


def check(text: str, user: str = AGENT_USER) -> list[str]:
    """Validate ``text`` (see :func:`parse_commands`); return the allowed template names."""
    return parse_commands(text, user)


def template_names_from_source(source: str) -> list[str]:
    """The template names declared in ``privilege/templates.rs`` (``service!`` and ``name:``)."""
    names = re.findall(r'service!\(\s*"(' + NAME.pattern + r')"', source)
    names += re.findall(r'^\s*name:\s*"(' + NAME.pattern + r')"', source, re.M)
    return names
